// path: app/lib/core/i18n.dart
// 다국어(ko/en/vi) 문자열 맵 — intl·코드생성 없이 직접 구현. {name} 형태 치환.
// 누락 키는 한국어로 대체, 그래도 없으면 키 자체를 표시. 베트남어는 원어민 검수 필요.

class I18n {
  static String lang = 'ko';
  static const supported = ['ko', 'en', 'vi'];
  static const names = {'ko': '한국어', 'en': 'English', 'vi': 'Tiếng Việt'};
}

String tr(String key, [Map<String, Object?> args = const {}]) {
  var s = dict[I18n.lang]?[key] ?? dict['ko']![key] ?? key;
  args.forEach((k, v) => s = s.replaceAll('{$k}', '${v ?? ''}'));
  return s;
}

